const order = $node['Webhook: WooCommerce Order'].json.body || $node['Webhook: WooCommerce Order'].json;
const customerId = $node['MySQL: Webklanten ophalen'].json.id;
const counter = $node['MySQL: Teller ophalen'].json.invoice_counter || '1';
const year = new Date().getFullYear();
const num = String(counter).padStart(4, '0');
const invoice_number = `F${year}-${num}`;

const total    = Math.round((parseFloat(order.total) || 0) * 100) / 100;
const totalTax = Math.round((parseFloat(order.total_tax) || 0) * 100) / 100;
const subtotal = Math.round((total - totalTax) * 100) / 100;

const today = (order.date_paid || order.date_created || new Date().toISOString()).split('T')[0];

// Regelitems
const lineItems     = order.line_items || [];
const shippingTotal = parseFloat(order.shipping_total) || 0;
const shippingTax   = parseFloat(order.shipping_tax) || 0;

const regels = lineItems.map(item => {
  const qty       = parseFloat(item.quantity) || 1;
  const itemTotal = parseFloat(item.total) || 0;
  const itemTax   = parseFloat(item.total_tax) || 0;
  const unitPrice = Math.round((itemTotal / qty) * 100) / 100;
  const btw_rate  = itemTotal > 0 ? Math.round(itemTax / itemTotal * 100) : 21;
  return {
    description: item.name,
    quantity:    qty,
    unit_price:  unitPrice,
    btw_rate:    btw_rate,
    btw_amount:  Math.round(itemTax * 100) / 100,
    total:       Math.round((itemTotal + itemTax) * 100) / 100
  };
});

if (shippingTotal > 0) {
  const btwRate = shippingTax > 0 ? Math.round(shippingTax / shippingTotal * 100) : 21;
  regels.push({
    description: 'Verzendkosten',
    quantity:    1,
    unit_price:  shippingTotal,
    btw_rate:    btwRate,
    btw_amount:  Math.round(shippingTax * 100) / 100,
    total:       Math.round((shippingTotal + shippingTax) * 100) / 100
  });
}


// Omzet grootboek bepalen op basis van land
const country = (order.billing && order.billing.country) ? order.billing.country.toUpperCase() : 'NL';
const euCountries = ["AT", "BE", "BG", "CY", "CZ", "DE", "DK", "EE", "ES", "FI", "FR", "GR", "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", "PL", "PT", "RO", "SE", "SI", "SK"];
let omzetCode;
if (country === 'NL') {
  omzetCode = '8000';
} else if (euCountries.includes(country)) {
  omzetCode = '8010';
} else {
  omzetCode = '8020';
}

return [{ json: {
  invoice_number,
  omzet_code: omzetCode,
  customer_id:   customerId,
  invoice_date:  today,
  due_date:      today,
  subtotal,
  btw_total:     totalTax,
  total,
  notes: `WooCommerce order #${order.number || order.id}`,
  regels
}}];

const data  = $node['Function: Data samenvoegen'].json;
const inv   = data.invoice_number;
const regels = data.regels;

const values = regels.map(r => {
  const desc = r.description.replace(/'/g, "''");
  return `('${inv}', '${desc}', ${r.quantity}, ${r.unit_price}, ${r.btw_rate}, ${r.btw_amount}, ${r.total})`;
}).join(',\n');

const query = `INSERT INTO invoice_items (invoice_number, description, quantity, unit_price, btw_rate, btw_amount, total) VALUES\n${values}`;
return [{ json: { query } }];
